mapper.update:
update users
nickname =#{dto.nickname}, bio =#{dto.bio}, gender =#{dto.gender}, birthday =#{dto.birthday}, relationship_status =#{dto.relationshipStatus}, hometown =#{dto.hometown}, avatar =#{dto.avatar},
where id = #{userId}

mapper.select:
select *from statuses left join status_images on statuses.id = status_images.status_id
and content like concat("%",#{q},"%") and user_id = #{userId}
order by statuses.created_at desc
